mapper.select:
SELECT COUNT(*)
FROM wf_process_monitor
WHERE start_time >= #{startDate}
AND tenant_id = #{tenantId}

    AND status = #{status}

SELECT COUNT(*)
FROM wf_process_monitor
WHERE status = #{status}
AND tenant_id = #{tenantId}

WITH daily_stats AS ( SELECT DATE_FORMAT(p.start_time, '%Y-%m-%d') as date, COUNT(*) as started, SUM(CASE WHEN p.status = 'COMPLETED' THEN 1 ELSE 0 END) as completed, p.tenant_id as tenant_id FROM wf_process_monitor p WHERE p.start_time >= #{startDate} AND p.tenant_id = #{tenantId}
AND p.process_def_key = #{processDefKey}
GROUP BY DATE_FORMAT(p.start_time, '%Y-%m-%d'), p.tenant_id ) SELECT ds.date, ds.started, ds.completed, COALESCE((SELECT COUNT(*) FROM wf_timeout_alert ta WHERE DATE_FORMAT(ta.alert_time, '%Y-%m-%d') = ds.date AND ta.tenant_id = #{tenantId}), 0) as timeout, COALESCE((SELECT COUNT(*) FROM wf_anomaly_alert aa WHERE DATE_FORMAT(aa.create_time, '%Y-%m-%d') = ds.date AND aa.tenant_id = #{tenantId}), 0) as anomaly FROM daily_stats ds ORDER BY ds.date DESC

SELECT p.id, p.instance_id, p.process_def_id, p.process_def_key, p.process_def_name as process_name, p.status, p.start_time, p.end_time, COALESCE(p.duration, TIMESTAMPDIFF(SECOND, p.start_time, NOW()) * 1000) as duration_ms, p.task_count, p.task_count as completed_task_count, p.start_user_name as initiator, p.start_user_name as initiator_name, p.create_time FROM wf_process_monitor p
p.tenant_id = #{tenantId}
AND p.process_def_key = #{processDefKey}
AND p.status = #{status}
AND p.start_time >= #{startTimeFrom}
AND p.start_time <= #{startTimeTo}
ORDER BY p.start_time DESC

SELECT 
    COUNT(*) as totalCount,
    SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) as completedCount,
    SUM(CASE WHEN status = 'RUNNING' THEN 1 ELSE 0 END) as runningCount,
    SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END) as failedCount,
    AVG(CASE WHEN status = 'COMPLETED' AND duration IS NOT NULL THEN duration ELSE NULL END) as avgDuration,
    MAX(CASE WHEN status = 'COMPLETED' AND duration IS NOT NULL THEN duration ELSE NULL END) as maxDuration,
    MIN(CASE WHEN status = 'COMPLETED' AND duration IS NOT NULL THEN duration ELSE NULL END) as minDuration
FROM wf_process_monitor
WHERE tenant_id = #{tenantId}

    AND process_def_key = #{processDefKey}


    AND start_time >= #{startTime}


    AND start_time <= #{endTime}

SELECT p.id, p.instance_id, p.process_def_id, p.process_def_key, p.process_def_name as process_name, p.status, p.start_time, p.end_time, COALESCE(p.duration, TIMESTAMPDIFF(SECOND, p.start_time, NOW()) * 1000) as duration_ms, p.task_count, p.task_count as completed_task_count, p.start_user_name as initiator, p.start_user_name as initiator_name, p.create_time FROM wf_process_monitor p WHERE p.tenant_id = #{tenantId}
AND p.start_time >= #{startTime}
AND p.start_time <= #{endTime}
ORDER BY p.start_time DESC
